<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/doctor_online_v580.php';if(!do580_enabled()){http_response_code(404);exit('Doctor Online module unavailable.');}$filters=['q'=>trim((string)($_GET['q']??'')),'specialty_id'=>(int)($_GET['specialty_id']??0),'org_id'=>(int)($_GET['org_id']??0),'online'=>!empty($_GET['online']),'sort'=>(string)($_GET['sort']??'')];$docs=do580_doctors($filters,120);$specialties=do580_specialties();$orgs=do580_organizations();do580_track('find_doctor_view','search',null,['specialty_id'=>$filters['specialty_id'],'online'=>$filters['online']?1:0]);do580_public_header('Find Doctors','Search approved city doctors by specialty, availability, hospital or clinic.');
?>
<section class="do580-pagehead"><div class="do580-shell"><h1>Find the right doctor</h1><p>Search approved doctors by specialty, availability, fee and local healthcare facility.</p></div></section>
<main class="do580-shell"><form class="do580-filter" id="doctor-filter"><input name="q" value="<?=e($filters['q'])?>" placeholder="Doctor, specialty, qualification or hospital"><select name="specialty_id"><option value="">All specialties</option><?php foreach($specialties as $s):?><option value="<?=(int)$s['id']?>" <?=$filters['specialty_id']==(int)$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select><select name="org_id"><option value="">All hospitals / clinics</option><?php foreach($orgs as $o):?><option value="<?=(int)$o['id']?>" <?=$filters['org_id']==(int)$o['id']?'selected':''?>><?=e($o['name'])?></option><?php endforeach;?></select><button class="do580-btn primary">Search</button><label style="grid-column:1/-1;display:flex;align-items:center;gap:8px;font-size:13px;color:#586b80"><input type="checkbox" name="online" value="1" <?=$filters['online']?'checked':''?> style="width:auto"> Show doctors online now <span style="margin-left:auto">Sort: <select name="sort" onchange="this.form.submit()"><option value="">Recommended</option><option value="fee" <?=$filters['sort']==='fee'?'selected':''?>>Lowest online fee</option></select></span></label></form>
<div class="do580-head"><div><span>SEARCH RESULTS</span><h2><?=count($docs)?> doctor<?=count($docs)===1?'':'s'?> found</h2></div></div>
<div class="do580-doctor-grid"><?php foreach($docs as $d):?><article class="do580-doctor-card"><div class="do580-doctor-cover"></div><div class="profile"><div class="avatar"><?php if($d['photo_url']):?><img src="<?=e($d['photo_url'])?>" alt="<?=e($d['display_name'])?>"><?php else:?><?=e(mb_strtoupper(mb_substr($d['display_name'],0,1)))?><?php endif;?></div><div class="do580-badges"><?php if($d['verified']):?><span class="do580-badge verified">VERIFIED</span><?php endif;?><?php if($d['online_status']==='available'):?><span class="do580-badge online">ONLINE NOW</span><?php endif;?><?php if($d['instant_consult']):?><span class="do580-badge">INSTANT</span><?php endif;?></div><h3><?=e($d['display_name'])?></h3><p><?=e($d['specialty_name']?:'Medical Doctor')?></p><p><?=e($d['qualification']?:'Qualification profile pending')?> · <?=max(0,(int)$d['experience_years'])?> years</p><p><?=e($d['organization_name']?:'Independent / Online')?></p><div class="do580-rating"><span><b>★ <?=number_format((float)$d['rating'],1)?></b> (<?=(int)$d['review_count']?>)</span><span><?=do580_money((float)$d['online_fee'])?> online</span></div><div class="do580-card-footer"><a href="/doctor-profile.php?id=<?=(int)$d['id']?>">Profile</a><a class="primary" href="/book-doctor.php?doctor=<?=(int)$d['id']?>">Book Appointment</a></div></div></article><?php endforeach;?><?php if(!$docs):?><div class="do580-panel"><h3>No matching doctors yet</h3><p>Try another specialty or remove the online-only filter. Doctors appear after healthcare admin verification.</p></div><?php endif;?></div>
</main>
<?php do580_public_footer(); ?>
